presets.css:
/* ========== 【区块1：顶栏】只在非设置的聊天页面生效 ========== */
.chat-thread:not(.chat-detail-mode) .chat-thread-pill {
  border-radius: 0 !important;
  margin: 0 -20px !important;
  width: calc(100% + 40px) !important;
  transform: translateY(-55px) !important;
  padding-bottom: 38px !important;
  background: #FFE0E8 !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  border-bottom: 1px solid rgba(0,0,0,0.04) !important;
  box-shadow: none !important;
  overflow: visible !important;
}

.chat-thread:not(.chat-detail-mode) .chat-thread-pill svg,
.chat-thread:not(.chat-detail-mode) .chat-thread-pill svg * {
  display: none !important;
}

.chat-thread:not(.chat-detail-mode) .chat-thread-pill .chat-back,
.chat-thread:not(.chat-detail-mode) .chat-thread-pill .chat-back-wrap {
  transform: translate(10px, 32px) !important;
  width: 15px !important;
  height: 15px !important;
  flex: 0 0 18px !important;
  font-size: 0 !important;
}
.chat-thread:not(.chat-detail-mode) .chat-thread-pill .chat-back::after,
.chat-thread:not(.chat-detail-mode) .chat-thread-pill .chat-back-wrap::after {
  content: '' !important;
  display: block !important;
  width: 15px !important;
  height: 15px !important;
  background-image: url('data:image/svg+xml;base64,') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

.chat-thread:not(.chat-detail-mode) .chat-thread-pill .chat-thread-head-more {
  transform: translate(-10px, 32px) !important;
  width: 23px !important;
  height: 23px !important;
  flex: 0 0 18px !important;
  font-size: 0 !important;
}
.chat-thread:not(.chat-detail-mode) .chat-thread-pill .chat-thread-head-more::after {
  content: '' !important;
  display: block !important;
  width: 18px !important;
  height: 18px !important;
  background-image: url('data:image/svg+xml;base64,') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

.chat-thread:not(.chat-detail-mode) .chat-thread-pill .chat-thread-center {
  position: relative !important;
  transform: translateY(35px) !important;
  padding-left: 46px !important;
}

.chat-thread:not(.chat-detail-mode) .chat-thread-pill .chat-thread-center::before {
  content: '' !important;
  position: absolute !important;
  left: -90px !important;
  top: 20% !important;
  transform: translateY(-50%) !important;
  width: 32px !important;
  height: 32px !important;
  border-radius: 50% !important;
  background-image: url('https://s41.ax1x.com/2026/08/16/pmXsAn1.jpg') !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  z-index: 99 !important;
}

.chat-thread:not(.chat-detail-mode) .chat-thread-pill .chat-thread-center h2 {
  transform: translate(-100px, -10px) !important;
  margin: 0 !important;
  text-align: left !important;
  font-size: 13px !important;
  color: #111111 !important;
}

.chat-thread:not(.chat-detail-mode) .chat-thread-pill .chat-thread-center::after {
  content: "5分钟前在线" !important;
  position: absolute !important;
  font-size: 11px !important;
  color: #666666 !important;
  left: -54px !important;
  top: 45% !important;
  z-index: 99 !important;
  padding-left: 14px !important;
  background-image: url('data:image/svg+xml;utf8,<svg width="24" height="24" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M24 44C29.5228 44 34.5228 41.7614 38.1421 38.1421C41.7614 34.5228 44 29.5228 44 24C44 18.4772 41.7614 13.4772 38.1421 9.85786C34.5228 6.23858 29.5228 4 24 4C18.4772 4 13.4772 6.23858 9.85786 9.85786C6.23858 13.4772 4 18.4772 4 24C4 29.5228 6.23858 34.5228 9.85786 38.1421C13.4772 41.7614 18.4772 44 24 44Z" fill="none" stroke="%23333" stroke-width="4" stroke-linejoin="round"/><path d="M16 24L22 30L34 18" stroke="%23333" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>') !important;
  background-size: 12px 12px !important;
  background-repeat: no-repeat !important;
  background-position: left center !important;
  line-height: 12px !important;
  white-space: nowrap !important;
}

/* ========== 【区块2：消息行 / 头像 / 昵称 / 头像框 / 隐藏时间戳】 ========== */
.chat-msg,
.chat-msg-body,
.chat-swipe-host,
.chat-swipe-content,
.chat-longpress-host {
  overflow: visible;
}

.chat-msg {
  display: flex !important;
  align-items: flex-end !important;
}
.chat-msg.is-me {}
.chat-msg.is-them {}

div:has(> .chat-msg.is-them) + div:has(> .chat-msg.is-them) > .chat-msg,
div:has(> .chat-msg.is-me) + div:has(> .chat-msg.is-me) > .chat-msg {
  align-items: flex-start !important;
}

div:has(> .chat-msg.is-them) + div:has(> .chat-msg.is-them) .chat-msg-name,
div:has(> .chat-msg.is-me) + div:has(> .chat-msg.is-me) .chat-msg-name {
  display: none !important;
}

div:has(> .chat-msg.is-them) + div:has(> .chat-msg.is-them) .chat-ava,
div:has(> .chat-msg.is-me) + div:has(> .chat-msg.is-me) .chat-ava {
  margin-top: 0 !important;
}

.chat-msg-name {
  font-size: 11px;
  opacity: 1;
  color: #c86888 !important;
}

.chat-msg-time,
.chat-msg-timestamp {
  display: none !important;
}

.chat-ava,
.chat-ava-sm {
  position: relative;
  overflow: visible;
  flex-shrink: 0;
}

.chat-ava img,
.chat-ava-img {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  display: block;
}

/* 头像框：仅聊天页生效 */
.chat-thread .chat-ava::after {
  content: '' !important;
  position: absolute !important;
  top: -14px !important;
  left: -10px;
  right: -10px;
  bottom: -10px;
  background-image: url('https://s41.ax1x.com/2026/08/19/pmvBJN8.png') !important;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  pointer-events: none;
  z-index: 999;
}

.chat-thread .chat-ava-sm::after {
  top: -6px;
  left: -6px;
  right: -6px;
  bottom: -6px;
}

/* 气泡通用 */
.chat-bubble {
  line-height: 1.0;
}

/* 对方气泡 */
.chat-msg.is-them .chat-bubble {
  background: #fff9dd !important;
  color: #5f5f5f !important;
  border: 1.2px solid rgba(0, 0, 0, 0.12) !important;
  border-radius: 18px !important;
  box-shadow: none !important;
  padding: 5px 10px !important;
  font-size: 12px !important;
  line-height: 1.35 !important;
  max-width: 220px !important;
}

/* 我方气泡 */
.chat-msg.is-me .chat-bubble {
  background: #ffe0e8 !important;
  color: #5f5f5f !important;
  border: 1.2px solid rgba(0, 0, 0, 0.10) !important;
  border-radius: 18px !important;
  box-shadow: none !important;
  padding: 5px 10px !important;
  font-size: 12px !important;
  line-height: 1.35 !important;
  max-width: 220px !important;
}

.chat-msg.is-them .chat-bubble::before,
.chat-msg.is-me .chat-bubble::before {
  display: none !important;
}

.chat-bubble {
  box-shadow: none !important;
}

/* ========== 【区块4：底栏输入框】 ========== */
.chat-thread {
  --dress-compose-bar-bg: #FFE0E8;
  --dress-compose-bar-fg: var(--ink);
  --dress-compose-bar-radius: 0;
  --dress-compose-bar-border: none;
  --dress-compose-bar-shadow: none;
  --dress-compose-bar-blur: none;
}

.chat-compose {
  background: transparent !important;
  box-shadow: none !important;
  position: static !important;
  padding: 0 !important;
  margin: 0 !important;
}

.chat-compose-bar {
  border-radius: 0 !important;
  background: #FFE0E8 !important;
  border: none !important;
  border-top: 1px solid rgba(0,0,0,0.04) !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  position: sticky !important;
  bottom: 0 !important;
  width: 100% !important;
  box-sizing: border-box !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 8px !important;
  padding: 8px 12px calc(env(safe-area-inset-bottom, 0px) + 4px) 12px !important;
  margin: 0 !important;
}

.chat-compose-input {
  flex: 1 1 300px !important;
  min-width: 200px !important;
  max-width: none !important;
  width: 280px !important;
  height: 36px !important;
  line-height: 24px !important;
  box-sizing: border-box !important;
  background: #FFF9DD !important;
  border-radius: 10px !important;
  padding: 6px 10px !important;
  text-align: left !important;
  margin: 0 auto !important;
}

.chat-room,
.chat-thread,
.message-list,
.messages,
.msg-list,
.scroll-area,
.chat-scroll,
[class*="message"][class*="list"],
[class*="chat"][class*="scroll"] {
  padding-bottom: 0 !important;
  margin-bottom: 0 !important;
}

.message-row:last-child,
.message-row:last-of-type,
[class*="message"]:last-child,
[class*="bubble"]:last-child,
[class*="image"]:last-child,
[class*="sticker"]:last-child {
  margin-bottom: 0 !important;
  padding-bottom: 0 !important;
}

/* 自定义图标 */
.chat-compose-plus {
  font-size: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 26px !important;
  height: 26px !important;
  flex-shrink: 0 !important;
}
.chat-compose-plus svg { display: none !important; }
.chat-compose-plus::after {
  content: "" !important;
  width: 26px !important;
  height:26px !important;
  background-image: url("https://s41.ax1x.com/2026/08/19/pmvOLuj.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  transform: translateY(-4px) !important;
}

.chat-compose-icon {
  font-size: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 24px !important;
  height: 24px !important;
  flex-shrink: 0 !important;
}
.chat-compose-icon svg { display: none !important; }

.chat-compose-icon[aria-label*="语音"],
.chat-compose-icon[aria-label*="mic"],
.chat-compose-icon[aria-label*="voice"],
.chat-compose-icon[title*="语音"],
.chat-compose-icon[title*="mic"],
.chat-compose-icon[title*="voice"] {
  background-image: url("https://s41.ax1x.com/2026/08/19/pmvOODs.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

.chat-compose-icon[aria-label*="发送"],
.chat-compose-icon[aria-label*="send"],
.chat-compose-icon[title*="发送"],
.chat-compose-icon[title*="send"] {
  background-image: url("https://s41.ax1x.com/2026/08/19/pmvObvQ.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

.chat-compose-bar .chat-compose-icon:last-child {
  background-image: url("https://s41.ax1x.com/2026/08/19/pmvOvEq.png") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

/* ========== I. 表情 / 图片 ========== */
.chat-msg.has-sticker .chat-msg-body,
.chat-msg.has-image .chat-msg-body {
}
.chat-bubble-sticker {
width: 80px !important;
max-width: 80px !important;
height: auto !important;
}
.chat-msg.is-me .chat-bubble-sticker {
}
.puff-photo {
}
